# Run from the rENA repo root: Rscript wasm/test/fixtures/unit-circle-rs.R
#
# R reference values for the unit-circle node move (libena's
# move_nodes_to_unit_circle), for the rena-wasm, qe-ena and ENA.jl tests:
#   wasm/test/fixtures/unit-circle-rs.json
#   python/tests/fixtures/unit-circle-rs.json   (same content)
#   julia/test/unit_circle_rs.jl                 (same values, 1-based dims)
#
# Expected values come from the R implementation the C++ replaced
# (tests/testthat/helper-move-nodes-reference.R), not from libena. Its
# centroids are wrong for ordered networks (it read only the i < j
# connections), so the ordered cases take their nodes from it and their
# centroids from the directed weighting computed here in R.
#
# Each model keeps the first 16 units (rows are independent) and the first 3
# dimensions of the nodes (the move changes only two of them).
suppressPackageStartupMessages({
  pkgload::load_all(".", quiet = TRUE)
  library(jsonlite)
})
source("tests/testthat/helper-move-nodes-reference.R")

x <- read.csv("inst/extdata/rs.data.csv")
codes <- c("Data", "Technical.Constraints", "Performance.Parameters",
           "Client.and.Consultant.Requests", "Design.Reasoning", "Collaboration")
fit <- function(ordered) {
  suppressWarnings(
    x |> accumulate(c("Condition", "UserName"), codes, c("Condition", "GroupName"),
                    ordered = ordered, default_window = 4) |> model()
  )
}

directed_centroids <- function(set, nodes) {
  lw <- as.matrix(set$line.weights)
  w <- matrix(0, nrow(lw), length(codes))
  for (cn in colnames(lw)) {
    ab <- match(strsplit(cn, " & ", fixed = TRUE)[[1]], codes)
    w[, ab[1]] <- w[, ab[1]] + lw[, cn]
    if (ab[2] != ab[1]) w[, ab[2]] <- w[, ab[2]] + lw[, cn]
  }
  rs <- rowSums(w)
  w[rs != 0, ] <- w[rs != 0, ] / rs[rs != 0]
  w %*% nodes
}

keep_units <- 1:16
keep_dims <- 1:3
models <- list(unordered = fit(FALSE), ordered = fit(TRUE))
cases <- list(
  list(model = "unordered", mode = "equal",  dims = c(1, 2)),
  list(model = "unordered", mode = "radial", dims = c(1, 2)),
  list(model = "unordered", mode = "equal",  dims = c(3, 2)),
  list(model = "ordered",   mode = "equal",  dims = c(1, 2)),
  list(model = "ordered",   mode = "radial", dims = c(1, 2))
)

for (k in seq_along(cases)) {
  cs <- cases[[k]]
  set <- models[[cs$model]]
  dn <- colnames(as.matrix(set$rotation$nodes))[cs$dims]
  f <- if (cs$mode == "equal") ref_move_nodes_to_unit_circle_with_equal_space
       else ref_move_nodes_to_unit_circle
  moved <- f(set, dn[1], dn[2])
  nodes <- as.matrix(moved$rotation$nodes)
  centroids <- if (cs$model == "ordered") directed_centroids(set, nodes)
               else as.matrix(moved$model$centroids)
  cases[[k]]$nodes <- unname(nodes[, keep_dims])
  cases[[k]]$centroids <- unname(centroids[keep_units, keep_dims])
}

model_json <- lapply(models, function(set) list(
  directed = is(set, "ena.ordered.set"),
  units = as.character(set$model$unit.labels)[keep_units],
  line_weights = unname(as.matrix(set$line.weights)[keep_units, ]),
  nodes = unname(as.matrix(set$rotation$nodes)[, keep_dims])
))

# JSON: 0-based dims, matrices as arrays of rows.
out <- list(
  generator = "wasm/test/fixtures/unit-circle-rs.R",
  rENA = as.character(packageVersion("rENA")),
  codes = codes,
  models = model_json,
  cases = lapply(cases, function(cs) c(cs[c("model", "mode")], list(dims = cs$dims - 1),
                                       cs[c("nodes", "centroids")]))
)
json <- toJSON(out, auto_unbox = TRUE, digits = I(17), matrix = "rowmajor")
writeLines(json, "wasm/test/fixtures/unit-circle-rs.json")
dir.create("python/tests/fixtures", showWarnings = FALSE)
writeLines(json, "python/tests/fixtures/unit-circle-rs.json")

# Julia: the same values as literals, 1-based dims.
jl_mat <- function(m) {
  rows <- apply(m, 1, function(r) paste(sprintf("%.17g", r), collapse = " "))
  paste0("[\n        ", paste(rows, collapse = ";\n        "), "]")
}
jl <- c(
  "# Generated by wasm/test/fixtures/unit-circle-rs.R from rENA's R reference",
  "# implementation; do not edit. See that script for what the values are.",
  "",
  "const UC_MODELS = Dict(",
  vapply(names(model_json), function(nm) {
    m <- model_json[[nm]]
    sprintf('    "%s" => (directed = %s,\n      line_weights = %s,\n      nodes = %s),',
            nm, tolower(m$directed), jl_mat(m$line_weights), jl_mat(m$nodes))
  }, ""),
  ")",
  "",
  "const UC_CASES = [",
  vapply(cases, function(cs) {
    sprintf('    (model = "%s", mode = "%s", dims = (%d, %d),\n      nodes = %s,\n      centroids = %s),',
            cs$model, cs$mode, cs$dims[1], cs$dims[2], jl_mat(cs$nodes), jl_mat(cs$centroids))
  }, ""),
  "]"
)
writeLines(jl, "julia/test/unit_circle_rs.jl")
cat("ok\n")
